let btn = gpio.button(9, {
    pull: "up",
    debounce_ms: 25,
    click_ms: 350,
    double_click_ms: 250,
    long_press_ms: 800
});

while (true) {
    let evt = btn.wait(); // Ожидание события без нагрузки на CPU
    if (evt == "click") {
        print(">>> Одиночный клик!");
        gpio.write(15, 1);
    } else if (evt == "double_click") {
        print(">>> Двойной клик!");
        gpio.write(15, 0);
    } else if (evt == "long_press") {
        print(">>> Длинное удержание!");
        rgb.set(8, 255, 0, 0);
    } else if (evt == "release") {
        print(">>> Кнопка отпущена");
        rgb.set(8, 0, 0, 0);
    }
}
